<script setup lang="ts">
import { computed,ref,onMounted,onUnmounted,watch } from 'vue'
import { useRouter } from 'vue-router'
import { loadPasswordPolicy,passwordError } from './passwordPolicy'
onMounted(()=>{void loadPasswordPolicy().catch(()=>{})})
import {previewAppearance,cancelAppearancePreview,rememberAppearance} from '../ui/theme'
import type {Appearance} from '../blog/types'
import { request } from '../api'
const router=useRouter(),key=ref(''),username=ref(''),password=ref(''),confirmation=ref(''),visible=ref(false),busy=ref(false),error=ref(''),checks=ref<any>(null)
const homeLayout=ref('grid2'),backup=ref({frequency:'daily',weekday:0,hour:2,minute:0,timezone:'Asia/Shanghai',keep:7})
const title=ref('Life Journal'),subtitle=ref(''),description=ref('收藏日常，留住时光。'),theme=ref('celadon'),style=ref('modern-soft'),palette=ref('celadon'),mode=ref('system')
const appearanceOwner=Symbol('setup-appearance')
const appearance=computed(()=>({theme:theme.value,style:style.value,palette:palette.value,mode:mode.value}) as Appearance)
watch(appearance,value=>previewAppearance(appearanceOwner,value),{immediate:true})
onUnmounted(()=>cancelAppearancePreview(appearanceOwner))
const valid=computed(()=>!passwordError(password.value)&&password.value===confirmation.value)
async function check(){busy.value=true;error.value='';try{checks.value=await request('/setup/check',{method:'POST',headers:{Authorization:'Bearer '+key.value}})}catch(e){error.value=String(e)+'。请检查数据库健康状态、镜像版本、媒体目录权限和初始化授权配置；不要清空数据库或关闭安全保护。'}finally{busy.value=false}}
async function finish(){if(!valid.value)return;busy.value=true;error.value='';try{await request('/setup/complete',{method:'POST',headers:{Authorization:'Bearer '+key.value},body:JSON.stringify({username:username.value,password:password.value,title:title.value,subtitle:subtitle.value,description:description.value,home_layout:homeLayout.value,backup:backup.value,appearance:{theme:theme.value,style:style.value,palette:palette.value,mode:mode.value}})});rememberAppearance(appearance.value);key.value='';password.value='';confirmation.value='';await router.replace('/login')}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><main class="container setup-page"><span class="eyebrow">LIFE JOURNAL · FIRST RUN</span><h1>建立你的私人生活档案</h1><p>首次初始化仅创建新账号和默认配置，不覆盖已有数据。</p><p v-if="error" role="alert" class="error">{{error}}</p><section class="card"><h2>1 · 初始化授权与系统检查</h2><label>初始化授权密钥<input v-model="key" type="password" autocomplete="off" maxlength="2048" /></label><p>使用你在Docker Compose 或容器管理界面 中为 API 设置的 SETUP_KEY（至少32字符），不要将密钥发给他人。</p><button :disabled="busy||!key" @click="check">检查系统</button><div v-if="checks" role="status"><p>数据库：{{checks.postgresql}} · 结构：{{checks.schema}} · API：{{checks.api}}</p><p>媒体目录：{{checks.media_writable===null?'备份进行中，请稍后重新检查':checks.media_writable?'可写':'不可写，请检查 UID 10001 的目录权限'}}</p><p>维护服务：{{checks.maintenance.online?'在线':'尚未在线，可完成后前往系统状态检查'}} · SSD 备份：{{checks.maintenance.configured?'已就绪':'尚未就绪，请检查维护容器备份目录权限'}}</p><p>应用版本：{{checks.application_version}}</p></div></section><form v-if="checks" @submit.prevent="finish"><fieldset :disabled="busy||!checks.media_writable"><section class="card"><h2>2 · 创建管理员</h2><label>用户名<input v-model="username" required maxlength="100" autocomplete="username" /></label><label>密码<input v-model="password" :type="visible?'text':'password'" required maxlength="2048" autocomplete="new-password" /></label><button type="button" class="quiet" :aria-pressed="visible" @click="visible=!visible">{{visible?'隐藏密码':'显示密码'}}</button><p>密码至少 8 个字符，不强制数字、大小写字母或特殊字符。避免常见密码，推荐不常见的密码短语。</p><p>{{passwordError(password)||'符合基本规则；服务端仍会最终验证。'}}</p><label>确认密码<input v-model="confirmation" :type="visible?'text':'password'" required maxlength="2048" autocomplete="new-password" /></label><p v-if="confirmation&&password!==confirmation" role="alert">两次密码不一致。</p></section><section class="card"><h2>3 · 网站设置</h2><label>网站名称<input v-model="title" required maxlength="100" /></label><label>网站副标题（可选）<input v-model="subtitle" maxlength="200" /></label><label>网站简介<textarea v-model="description" maxlength="2000" /></label><label>风格<select v-model="style" aria-label="风格"><option value="modern-flat">Modern Flat</option><option value="editorial">Editorial</option><option value="modern-soft">Modern Soft</option><option value="glass">Glass</option></select></label><label>主题配色<select v-model="palette" aria-label="主题配色"><option value="celadon">晨雾青瓷</option><option value="lilac">丁香奶油</option></select></label><label>明暗模式<select v-model="mode" aria-label="明暗模式"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label><label>首页展示方式<select v-model="homeLayout"><option value="grid2">卡片阅读</option><option value="feature">杂志精选</option><option value="list">简洁列表</option></select></label><p>首页使用介绍与最新故事模块；完成后可在网站设置调整。将创建可编辑的旅行、礼物、相册和纪念日模板。</p></section><section class="card"><h2>4 · SSD 本地备份与确认</h2><p>Life Journal 自动将完整备份保存到 SSD。建议通过主机或 NAS 的备份任务，定期将备份目录复制到独立 HDD。</p><label>备份周期<select v-model="backup.frequency"><option value="daily">每天</option><option value="weekly">每周</option></select></label><label v-if="backup.frequency==='weekly'">每周执行日<select v-model.number="backup.weekday"><option v-for="(name,i) in ['一','二','三','四','五','六','日']" :key="i" :value="i">星期{{name}}</option></select></label><label>执行小时<input v-model.number="backup.hour" type="number" min="0" max="23" required /></label><label>执行分钟<input v-model.number="backup.minute" type="number" min="0" max="59" required /></label><label>保留数量<input v-model.number="backup.keep" type="number" min="1" max="52" required /></label><p>默认每天 02:00（Asia/Shanghai），保留最近7份；最后一次实际恢复验证副本额外保护，首次演练前暂停淘汰。备份周期和保留数量可在“备份与恢复”调整。</p><p>初始化：{{title}} · 管理员 {{username}}。完成后请登录；初始化入口将关闭。</p><button :disabled="!valid||busy||!title.trim()||!username.trim()">{{busy?'正在初始化…':'确认并完成初始化'}}</button></section></fieldset></form></main></template>
<style scoped>.setup-page{max-width:760px}.setup-page .card{margin-block:1.5rem}.setup-page fieldset{border:0;padding:0;min-width:0}.setup-page input,.setup-page textarea{max-width:100%;box-sizing:border-box}</style>
